\label{prop1}
  Suppose that $u\in\mathcal{S}'(\mathbb R^d)$ is a solution to $(\Delta-k^2(1+q))u=0$ in
  $B_R^c(0).$ If $u\in L^2(B_R^c(0))$ then $u$ vanishes in this set.

\label{propNew2}
  For each $j$ there is a finite number of non-positive values
  $\{\lambda_{jl}:\: l=1,\dots, N_j\},$ which arise as the
  non-positive point spectrum of the operators in~\eqref{eqn112.405}
  and~\eqref{eqn114.400}. The indicial operator
  $\widehat{N}_{\operatorname{ff}_j,0}(\kappa^2\mathcal{D}^{\epsilon_j,\mu_j})(\tau)-\omega^2\kappa_j^2$
  is invertible for $\omega\kappa_0<|\tau|<\omega\kappa_j^{\max},$
  except for
  \begin{equation}
    \pm\tau^1_{jl}=\pm\sqrt{\omega^2\kappa_0^2-\lambda_{jl}},\, l=1,\dots, N_j.
  \end{equation}
  It is invertible for $\tau\geq \omega\kappa^{\max}_j.$

The second part of the proposition gives a condition for the group
    velocity and phase velocity to have the same sign that is
    independent of $\omega.$ The same result holds for bi-infinite
    wave-guides with piecewise constant $\kappa(x').$ The proof gives
    an explicit bound:
    \begin{equation}\label{eqn154.700}
      \dot{\lambda}_l(\tau_0)+2\tau_0>\omega\kappa_0\left[2-\left(\frac{\kappa^{\max}_j}{\kappa_0}
        \right)^2\right]\left[1+\left(\frac{\kappa^{\max}_j}{\kappa_0}\right)^2\right].
    \end{equation}

The proof of 1. is straightforward: From~\eqref{eqn138.400} we
    know that $|\dot{\lambda}_l(\tau)|<2\sqrt{2}\|d\mathfrak l\|_{L^{\infty}};$ on
    the other hand, for~\eqref{eqn138.500} to hold, $\tau_0$ must be
    greater than $\sqrt{\lambda}.$
    Therefore~\eqref{eqn139.500} holds if
  \begin{equation}
    \sqrt{2}\|d\log\kappa_j\|_{L^{\infty}}\leq\sqrt{\lambda}.
  \end{equation}

  The proof of 2. is more involved.  Let $\check{\xi}_{\tau}$ denote an analytic family
  of normalized solutions to
  $$L_{\tau,j}\check{\xi}_{\tau}=\lambda(\tau)\check{\xi}_{\tau},$$
  with $\lambda(\tau_0)=\omega^2\kappa_0^2-\tau_0^2.$ To simplify the notation we omit
  the $j$ and $\tau$ subscripts. 
  Integrating by parts, the PDE implies that
  \begin{equation}\label{eqn153}
    \|\frac{1}{\sqrt{\mu}}d_{\tau}\sqrt{\mu}\check{\xi}\|^2+
    \|\frac{1}{\epsilon\sqrt{\mu}}d^*_{\tau}\epsilon\sqrt{\mu}\check{\xi}\|^2=
    \omega^2\|\kappa\check{\xi}\|^2.
  \end{equation}
  As before, let
  $\check{\xi}=\check{\xi}_1dx_1+\breve{\xi},$ and again use formula~\eqref{eqn110.223},
  which states
  \begin{equation}
    2q=\dot{\lambda}(\tau_0)=-4\operatorname{Im}\langle \check{\xi}_{1},d_2\log\kappa\lrcorner\breve{\xi}\rangle.
  \end{equation}
  We need to show that
  \begin{equation}
    g=2(\tau_0+q)>0.
  \end{equation}

  Letting $G=\kappa^{-2}_0-\kappa^{-2}\geq 0,$ and using the identity
  \begin{equation}
 \kappa^{-2}d_2\log\kappa=-\frac{1}{2}d_2\kappa^{-2},
  \end{equation}
  we write
  \begin{equation}
    q=-2\operatorname{Im}\langle
    \sqrt{\mu}\check{\xi}_1,\kappa^{-2}d_2\log\kappa\lrcorner\epsilon\sqrt{\mu}\breve{\xi})=
    -\operatorname{Im}\langle\sqrt{\mu}\check{\xi}_1,d_2 G\lrcorner\epsilon\sqrt{\mu}\breve{\xi}\rangle.
  \end{equation}
  Using the fact that $d_2^*(f\alpha)=fd^*\alpha-df\lrcorner\alpha,$ and
  integrating by parts we let $q=q_1+q_2,$ where
  \begin{equation}
 q_1=\operatorname{Im}\langle d_2(\sqrt{\mu}\check{\xi}_1),G\epsilon\sqrt{\mu}\breve{\xi}\rangle,\quad
 q_2=-\operatorname{Im}\langle\sqrt{\mu}\check{\xi}_1,G d_2^*(\epsilon\sqrt{\mu}\breve{\xi})\rangle.
  \end{equation}

  We easily show that for a 1-form $\theta=\theta_1dx_1+\breve{\theta}$
  \begin{equation}
    \|\mu^{-\frac 12}d_{\tau}\theta\|^2=\|\mu^{-\frac
      12}d_{2}\breve{\theta}\|^2+
    \|\mu^{-\frac 12}(d_{2}\theta_1-i\tau_0\breve{\theta})\|^2.
  \end{equation}
  Applying this with $\theta=\sqrt{\mu}\check{\xi},$ and using~\eqref{eqn153}
  shows that
  \begin{equation}
    \|\mu^{-\frac
      12}(d_{2}\sqrt{\mu}\check{\xi}_1-i\tau_0\sqrt{\mu}\breve{\xi})\|^2\leq
    \omega^2\|\kappa\check{\xi}\|^2.
  \end{equation}
  Using this identity and the Cauchy-Schwarz inequality  shows that
  \begin{equation}
    \begin{split}
    q_1&=-\operatorname{Im}\langle\mu^{-\frac 12}
    (d_{2}\sqrt{\mu}\check{\xi}_1-i\tau_0\sqrt{\mu}\breve{\xi})
    ,G\kappa^2\breve{\xi}\rangle+
    \tau_0\|G^{\frac 12}\kappa\breve{\xi}\|^2\\ &\geq
    -\omega\left(\frac{\kappa_1^2}{\kappa_0^2}-1\right)^{\frac 12}
    \|\kappa\check{\xi}\|\|G^{\frac 12}\kappa\breve{\xi}\|+\tau_0\|G^{\frac
      12}\kappa\breve{\xi}\|^2.
    \end{split}
  \end{equation}

  To estimate $q_2$ we use the identity
  $d_{\tau}^*\theta=d_2^*\breve{\theta}-i\tau\theta_1$ to rewrite
  \begin{equation}
    q_2=-\operatorname{Im}\left\langle\kappa^2
    G\check{\xi}_1,\frac{1}{\epsilon\sqrt{\mu}}d_{\tau}^*(\epsilon\sqrt{\mu}\check{\xi})\right\rangle+
    \tau_0\|\kappa G^{\frac 12}\check{\xi}_1\|^2.
  \end{equation}
  As~\eqref{eqn153} implies that
  $\|(\epsilon\sqrt{\mu})^{-1}d_{\tau}^*(\epsilon\sqrt{\mu}\check{\xi})\|\leq \omega\|\kappa\check{\xi}\|,$
    we see that
    \begin{equation}
      q_2\geq
      -\omega\left(\frac{\kappa_1^2}{\kappa_0^2}-1\right)^{\frac
        12}\|\kappa\check{\xi}\|
      \|G^{\frac 12}\kappa\check{\xi}_1\|+\tau_0\|\kappa G^{\frac 12}\check{\xi}_1\|^2.
    \end{equation}

    Let $\kappa_1=\kappa_j^{\max}$; combining these estimates gives the lower bound:
    \begin{equation}
            g\geq 2[\tau_0+\tau_0\|\kappa G^{\frac 12}\check{\xi}\|^2-
        \omega\kappa_1(\|G^{\frac 12}\kappa\check{\xi}_1\|+\|G^{\frac 12}\kappa\breve{\xi}\|)].
    \end{equation}
   as $\omega\kappa_0\leq\tau_0,$ this estimate
    implies that
    \begin{equation}\label{eqn169}
      g\geq 2\omega\kappa_0\left[1-\sqrt{2}\frac{\kappa_1}{\kappa_0}
        \left(\frac{\kappa_1^2}{\kappa_0^2}-1\right)^{\frac
          12}\|\kappa G^{\frac 12}\check{\xi}\|+\|\kappa G^{\frac
          12}\check{\xi}\|^2\right].
    \end{equation}
    The polynomial $1-\lambda
    x+x^2$ is strictly positive if  $\lambda<2,$ which is the
    case in \eqref{eqn169} if $\frac{\kappa_1}{\kappa_0}<\sqrt{2}.$ In
    this case the minimum value is $1-\frac{\lambda^2}{4}.$

If the wave-guide mode, $\check{\xi}_{\tau_0}$ used in the proof happens
    to be either divergence-free or curl-free, then we can improve
    the estimate in~\eqref{eqn169} to
    \begin{equation}
      g\geq 2\omega\kappa_0\left[1-\frac{\kappa_1}{\kappa_0}
        \left(\frac{\kappa_1^2}{\kappa_0^2}-1\right)^{\frac
          12}\|\kappa G^{\frac 12}\check{\xi}\|+\|\kappa G^{\frac
          12}\check{\xi}\|^2\right].
    \end{equation}
    This quantity is positive if
    \begin{equation}
      \frac{\kappa_1}{\kappa_0}
      <\sqrt{\frac{1+\sqrt{17}}{2}},
    \end{equation}
   which is larger than 1.6. Even though wave-guide modes can always be split into a
   divergence-free part and a curl-free part, it is by no means
   obvious that an analytic analytic family of eigenfunctions
   $\{\check{\xi}_{\tau}\}$ satisfying
   \begin{equation}
     L_{\tau,j}\check{\xi}_{\tau}=\lambda(\tau)\check{\xi}(\tau),
   \end{equation}
   with $\lambda(\tau_0)=\omega^2\kappa_0^2-\tau_0^2$ can be split in
   this way. So we cannot generally replace the $\sqrt{2}$
   in~\eqref{cntrst_ratio_est} with this larger number.

\label{rmk8.500}
  Let $c>0,$ and define
  \begin{equation}\label{eqn5.89.93}
    \lambda_M(c)=\inf\{\mu:\text{ if~\eqref{eqn138.500} holds
        for a }\lambda>\mu,\text{ then } \dot{\lambda}_l(\tau_0)+2\tau_0\geq c\}.
  \end{equation}
  We let $\mathcal I_M(c)=(\lambda_M(c),\infty)$ be the \emph{Mourre interval};
  we will be able to prove a Mourre estimate for energies in $\mathcal I_M.$ It
  follows from Proposition~\ref{prop4} that, for some $c>0,$
  $\lambda_M(c)$ is finite. It remains a very interesting question
  whether or not $\lambda_M(c)\to 0,$ as $c\to 0.$

Proposition~\ref{prop4} shows that these hypotheses are satisfied if either
    \begin{equation}
      \sqrt{2}\|d_2\log\kappa_j\|_{L^{\infty}}<\omega\kappa_0,\text{
        or }
   \frac{\kappa_j^{\max}}{\kappa_0}<\sqrt{2},
    \end{equation}
    for $j=1,\dots,m.$ It seems likely that these are not sharp and
    that uniqueness will hold much more generally.

    Using standard elliptic estimates one can show that if
    $2\|x\cdot\nabla_x\log\kappa\|_{L^{\infty}}<1,$ then the set $\mathcal E$
    is bounded and therefore finite. There is a similar statement for
    incoming solutions.

\label{IdMourreConst}
 Suppose $\lambda\in\mathbb{R}$. We say that the {\em ideal Mourre constant} at the level of an eigenvalue
$\lambda'=\lambda-|\xi_a|^2$ of $H^a(y_a,\xi_a)$ with eigenprojector $E$ is $M^a_{(y_a,\xi_a)}(\lambda)$
\begin{equation}\label{eq:ideal-Mourre-constant}
M^a_{(y_a,\xi_a)}(\lambda)=2
(\lambda-\lambda')+C^a_{(y_a,\xi_a)}
\end{equation}
where $C^a_{(y_a,\xi_a)}(\lambda)$ is the largest constant (i.e.\ the
$\sup$ of all constants) such that
\begin{equation}\label{eq:ideal-Mourre-constant-2}
\lambda-\lambda'=|\xi_a|^2\Rightarrow
|\xi_a|E\Big[\frac{\xi_a}{|\xi_a|}\partial_{\xi_a},H^a\Big]E\geq C^a_{(y_a,\xi_a)}(\lambda) E.
\end{equation}
In case $\lambda'=\lambda-|\xi_a|^2$ is not an eigenvalue of
$H^a(y_a,\xi_a)$, we set $C^a_{(y_a,\xi_a)}(\lambda),$ and
$M^a_{(y_a,\xi_a)}(\lambda)$ to be $+\infty$.


We say that the ideal Mourre constant at the level of a subsystem
$a\in\mathcal{A}$ at energy $\lambda$ is
\begin{equation}\label{Ma_def}
M^a(\lambda)=\inf_{(y_a,\xi_a)}M^a_{(y_a,\xi_a)}(\lambda),
\end{equation}
understood to be $+\infty$ if $\lambda-|\xi_a|^2\notin \sigma_{\operatorname{pp}}(H^a(y_a,\xi_a))$ for all
$(y_a,\xi_a)$.

We say that $\hat V_a$ is $\tilde\delta_{1,a}$-small if the zeroth order,
`non-product', part of $\hat V_a$, namely $\hat V^1_a(y_a)\xi_a$ satisfies
\begin{equation}\label{eq:hat-V-1-est}
  |\hat V^1_a|\leq \tilde\delta_{1,a};
\end{equation}
notice that for $a=0$, $\tilde\delta_{1,0}=0$.

\label{Mourre+}
For all $\varepsilon>0$ there is $\delta>0$ such that for all smooth functions
$\phi\in{\mathcal C}^{\infty}_c((\lambda-\delta,\lambda+\delta);[0,1]),$ we have
\begin{equation}\label{eq:Mourre-0}
\phi(H)i[A,H]\phi(H)\geq {\color{black}(M'_1(\lambda)-\delta'_1(\lambda)-\varepsilon)} \color{black} \phi(H)^2+K',
\end{equation}
where $K'\in\Psi_{\mathrm{Sc}}^{-\infty,1}(\bar X,\mathcal{C})$ is a compact operator.

As we see below, in the wave-guide setting the Mourre estimate holds
 at $\lambda=\omega^2\kappa_0^2$ if
 \begin{equation}\label{eqn93.334}
  \sqrt{2} \|d\log\mathfrak l\|_{L^{\infty}}<\omega\kappa_0;
 \end{equation}
it also holds at $\lambda=\omega^2\kappa_0^2,$ for any $\omega,$
if the contrast ratios satisfy~\eqref{cntrst_ratio_est}.
In these cases a simpler proof of the Mourre estimate is available,
which we outline in Appendix~\ref{MourreEstMaxWG}.

\label{lem1}
    Let $q$ be a  first order operator whose coefficients are
    supported in $B_R(0)$. There is a constant $C>0,$ so that if
    $v\in L^2(\mathbb R^2)$ is a solution to
    \begin{equation}\label{eqn168.334}
      (-\Delta+q)v=-\lambda v,
    \end{equation}
    for a $\lambda>0,$ then
    \begin{equation}
      \|r\partial_r v\|^2_{L^2(B_1^c(0))}\leq 4\|v\|^2_{L^2}+C\|\nabla v\|^2_{L^2(B_R(0))}.
    \end{equation}
    The constant, $C,$ is independent of $\lambda.$

The statement $iE[w^bD_{w^b},H^b]E=0$ is formally a consequence of
\begin{equation*}
iE[w^bD_{w^b},H^b]E=iEw^b D_{w^b}(H^b-\lambda-|\xi_b|^2)E
-iE(H^b-\lambda-|\xi_b|^2)w^b D_{w^b}E=0,
\end{equation*}
but this requires justification since $w^b D_{w^b}$ is not bounded
on $L^2(X^b)$. In fact, by elliptic regularity
(namely using $E=E\phi(\hat H_b)$), the only issue is
the lack of decay of $w^b D_{w^b}$ at infinity, but the computation is
justified by replacing $w^b D_{w^b}$ by $\chi_0(|w^b|/C) w^bD_{w^b}$,
$\chi_0\inC^\infty_c(\mathbb{R})$ identically $1$ near $0$, and observing that
\begin{equation*}
\phi(\hat H_b)[\chi_0(w^b/C),H]w^bD_{w^b}
\end{equation*}
is uniformly bounded and
goes to $0$ strongly as $C\to\infty$.
